        <div style="font-size:12.5px;color:#B9B1D9;margin-top:4px;">Payment automation for Bangladesh</div>
      </td></tr>
      <tr><td style="height:4px;background-color:#EC008C;background-image:linear-gradient(90deg,#EC008C,#FF7A18);font-size:0;line-height:0;">&nbsp;</td></tr>
